package review

import (
	"fmt"
	"sort"
	"strings"

	"github.com/sevigo/code-warden/internal/core"
)

var severityRank = map[string]int{
	"critical": 4,
	"high":     3,
	"medium":   2,
	"low":      1,
}

func rank(sev string) int {
	return severityRank[strings.ToLower(sev)]
}

func findingKey(s core.Suggestion) string {
	file := strings.TrimPrefix(s.FilePath, "./")
	if s.LineNumber > 0 {
		return fmt.Sprintf("%s:%d", file, s.LineNumber)
	}
	return file
}

func Deduplicate(reviews []*core.StructuredReview) []core.Suggestion {
	seen := make(map[string]int)
	out := make([]core.Suggestion, 0, len(reviews))
	for _, r := range reviews {
		if r == nil {
			continue
		}
		for _, s := range r.Suggestions {
			key := findingKey(s)
			if idx, ok := seen[key]; ok {
				if rank(out[idx].Severity) < rank(s.Severity) {
					out[idx] = s
				}
				continue
			}
			seen[key] = len(out)
			out = append(out, s)
		}
	}
	return out
}

func SortBySeverity(suggestions []core.Suggestion) []core.Suggestion {
	out := make([]core.Suggestion, len(suggestions))
	copy(out, suggestions)
	sort.SliceStable(out, func(i, j int) bool {
		ri := rank(out[i].Severity)
		rj := rank(out[j].Severity)
		if ri != rj {
			return ri > rj
		}
		return out[i].LineNumber < out[j].LineNumber
	})
	return out
}
